const ut8 *
parse_dwarf_comp_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
	if (!s || !obuf || !cu || !da || !debug_str) {
		return NULL;
	}

	// Parse and expand the compilation unit
	if (!rb_dwarf_cu_init (cu, obuf, debug_str, debug_str_len)) {
		return NULL;
	}

	// Initialize the DIEs using the debug abbreviation
	if (!cu->die) {
		cu->die = r_bin_dwarf_abbrev_get (da, cu->abbrev_offset + offset);
		if (!cu->die) {
			return NULL;
		}
	}

	// Iterate through attributes and populate the database
	for (int i = 0; i < cu->die->n; i++) {
		RBinDwarfAbbrev *ab = &cu->die->abbrev[i];
		if (ab->attr && ab->form) {
			// Parse attribute and store in the database
			if (!rb_dwarf_attr_parse (s, ab->attr, ab->form, &obuf)) {
				return NULL;
			}
		}
	}

	// Handle the compilation directory if present
	const char *directory = sdb_get (s, "DW_AT_comp_dir", 0);
	if (directory) {
		cu->comp_dir = strdup (directory);
	}

	return obuf;
}

const ut8 *
parse_dwarf_compilation_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
	if (!s || !obuf || !cu || !da || !debug_str) {
		return NULL;
	}

	size_t init_len = obuf - (const ut8 *)obuf;
	const ut8 *cursor = obuf;

	// Parse the compilation unit header
	// (Assume that RBinDwarfCompUnit has appropriate fields for header info)

	// Read the abbreviation offset and version
	// (Assume a helper function like read_uleb128 is available)
	uint64_t abbr_offset = read_uleb128(&cursor);
	uint16_t version = read_uleb128(&cursor);
	uint64_t unit_abbr_offset = abbr_offset + offset;

	// Find the corresponding abbrev entry
	const RBinDwarfAbbrev *abbrev_entry = r_bin_dwarf_debug_abbrev_find_by_offset(da, unit_abbr_offset);
	if (!abbrev_entry) {
		return NULL;
	}

	// Parse the DIEs based on the abbreviation entry
	// (Assume that RBinDwarfCompUnit has a list or array for DIEs)
	RBinDwarfDie *die = NULL;
	for (const RBinDwarfAbbrev *abbrev = abbrev_entry; abbrev; abbrev = abbrev->next) {
		die = r_new0(RBinDwarfDie);
		if (!die) {
			return NULL;
		}

		// Parse the attributes for this DIE
		for (const RBinDwarfAbbrevAttr *attr = abbrev->attributes; attr; attr = attr->next) {
			switch (attr->type) {
				case DW_AT_name:
					// Parse a string attribute
					{
						const ut8 *name = cursor;
						size_t name_len = 0;
						while (name[name_len] != '\0' && name + name_len < obuf + init_len) {
							name_len++;
						}
						if (name_len == 0) {
							// No null terminator found, invalid string
							r_free(die);
							return NULL;
						}
						cu->name = r_str_ndup((const char *)name, name_len);
						cursor += name_len + 1;
					}
					break;
				case DW_AT_comp_dir:
					// Parse a string attribute and store in the database
					{
						const ut8 *dir = cursor;
						size_t dir_len = 0;
						while (dir[dir_len] != '\0' && dir + dir_len < obuf + init_len) {
							dir_len++;
						}
						if (dir_len == 0) {
							// No null terminator found, invalid string
							r_free(die);
							return NULL;
						}
						sdb_set(s, "comp_dir", (const char *)dir, 0);
						cursor += dir_len + 1;
					}
					break;
				default:
					// Skip unsupported attributes
					break;
			}
		}

		// Add the parsed DIE to the compilation unit
		r_list_push(cu->dies, die);
	}

	// Return the next position in the buffer after parsing
	return cursor;
}

const ut8 *parse_dwarf_compilation_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
	if (!s || !obuf || !cu || !da || debug_str_len == 0) {
		return NULL;
	}

	// Placeholder for buffer boundary checks
	if ((size_t)(obuf - (const ut8 *)obuf) < sizeof(RBinDwarfCompUnit)) {
		return NULL;
	}

	cu->offset = offset;
	cu->length = *(size_t *)obuf;

	// Skip length
	obuf += sizeof(size_t);

	// Parse abbreviation offset and version
	if ((size_t)(obuf - (const ut8 *)obuf) < sizeof(uint16_t) + sizeof(uint16_t)) {
		return NULL;
	}
	cu->version = *(uint16_t *)obuf;
	obuf += sizeof(uint16_t);
	cu->abbrev_offset = *(uint16_t *)obuf;
	obuf += sizeof(uint16_t);

	// Initialize compilation unit DIEs based on abbreviations
	if (cu->abbrev_offset >= da->count) {
		return NULL;
	}

	RBinDwarfAbbrevEntry *entry = &da->entries[cu->abbrev_offset];
	if (!entry) {
		return NULL;
	}

	cu->die_count = entry->count;

	for (int i = 0; i < entry->count; i++) {
		RBinDwarfDIE *die = &cu->dies[i];
		die->tag = entry->tags[i];
		die->attr_count = entry->attr_count[i];
		for (int j = 0; j < die->attr_count; j++) {
			die->attrs[j].name = entry->attr_names[i][j];
			die->attrs[j].form = entry->attr_forms[i][j];
		}
	}

	// Parse attributes and store in the database
	for (int i = 0; i < cu->die_count; i++) {
		RBinDwarfDIE *die = &cu->dies[i];
		for (int j = 0; j < die->attr_count; j++) {
			RBinDwarfAttr *attr = &die->attrs[j];
			char *key = sdb_fmt("dwarf.attr.%d.%d", i, j);
			switch (attr->form) {
				case DW_FORM_string:
					if ((size_t)(obuf - (const ut8 *)obuf) > debug_str_len) {
						return NULL;
					}
					attr->value = strdup ((const char *)obuf);
					sdb_set (s, key, attr->value, 0);
					break;
				default:
					break;
			}
		}
	}

	return obuf;
}

